// Simple token bucket with CKNE scaling (conceptual)
class TokenBucket {
  constructor(rate, burst) {
    this.rate = rate;
    this.burst = burst;
    this.tokens = burst;
    this.last = Date.now();
  }
  tick() {
    const now = Date.now();
    const dt = (now - this.last) / 1000;
    this.last = now;
    this.tokens = Math.min(this.burst, this.tokens + dt * this.rate);
  }
  tryConsume(n = 1) {
    this.tick();
    if (this.tokens >= n) { this.tokens -= n; return true; }
    return false;
  }
}
```

